import{_ as l,o as r,c as i,am as t}from"./chunks/framework.CiF4W93w.js";const p=JSON.parse('{"title":"中间件","description":"","frontmatter":{"title":"中间件","excerpt":"摘要","date":"2026-03-26 21:17:56","updated":"2026-03-26 21:17:56"},"headers":[],"relativePath":"中间件/index.md","filePath":"中间件/index.md","lastUpdated":null}'),e={name:"中间件/index.md"};function o(n,a,s,g,h,d){return r(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h3><p><a href="/java/中间件/中间件 - 消息队列/">Java体系——中间件 - 消息队列</a></p><h3 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h3><ul><li><a href="/java/中间件/技术栈 Redis/Caffeine本地缓存使用/">Caffeine本地缓存使用</a></li></ul><h3 id="数据库中间件" tabindex="-1">数据库中间件 <a class="header-anchor" href="#数据库中间件" aria-label="Permalink to &quot;数据库中间件&quot;">​</a></h3><p>当单机数据库不能满足需求时，需要用到数据库中间件来实现 <strong>分库分表、读写分离</strong>。</p><ul><li><strong>MyCat</strong>（开源分库分表、读写分离）</li><li><strong>ShardingSphere</strong>（Apache 项目，支持 Sharding-JDBC、Sharding-Proxy）</li><li><strong>Druid 连接池</strong>（性能分析、SQL 监控）</li><li><strong>TiDB</strong>（分布式 HTAP 数据库）</li></ul><p><strong>必须掌握的点：</strong></p><ul><li>分库分表原理与路由算法</li><li>分布式事务（XA、TCC、Seata）</li><li>数据一致性处理</li></ul><h3 id="搜索引擎中间件" tabindex="-1">搜索引擎中间件 <a class="header-anchor" href="#搜索引擎中间件" aria-label="Permalink to &quot;搜索引擎中间件&quot;">​</a></h3><p>当需要快速检索海量数据时，搜索引擎是必要组件。</p><ul><li><strong>Elasticsearch</strong>（ES，全文检索、日志分析） <ul><li>倒排索引原理</li><li>分片与副本机制</li><li>集群部署与索引优化</li></ul></li><li><strong>Solr</strong>（较老稳定，可替代 ES）</li></ul><h3 id="注册与配置中心" tabindex="-1">注册与配置中心 <a class="header-anchor" href="#注册与配置中心" aria-label="Permalink to &quot;注册与配置中心&quot;">​</a></h3><p>在微服务架构中，服务发现与配置管理是核心环节。</p><ul><li><strong>Eureka</strong>（Netflix 出品）</li><li><strong>Consul</strong>（支持健康检查、KV 存储）</li><li><strong>Zookeeper</strong>（强一致性，Dubbo 注册中心）</li><li><strong>Nacos</strong>（轻量级服务注册与配置中心，阿里开源）</li></ul><p><strong>需要掌握：</strong></p><ul><li>服务注册与发现流程</li><li>健康检查机制</li><li>动态配置刷新</li></ul><h3 id="api-网关" tabindex="-1">API 网关 <a class="header-anchor" href="#api-网关" aria-label="Permalink to &quot;API 网关&quot;">​</a></h3><p>用于统一入口、路由、鉴权、限流、负载均衡等。</p><ul><li><strong>Spring Cloud Gateway</strong>（响应式网关）</li><li><strong>Kong</strong>（支持插件扩展）</li><li><strong>Nginx</strong>（反向代理 + 负载均衡）</li></ul><hr><h3 id="分布式协调与任务调度" tabindex="-1">分布式协调与任务调度 <a class="header-anchor" href="#分布式协调与任务调度" aria-label="Permalink to &quot;分布式协调与任务调度&quot;">​</a></h3><ul><li><strong>Zookeeper</strong>（选主、分布式锁、配置管理）</li><li><strong>Quartz</strong>（定时任务调度）</li><li><strong>Elastic-Job</strong>、<strong>XXL-Job</strong>（分布式任务调度）</li></ul><p><a href="/java/中间件/中间件 - 分布式协调与任务调度/">中间件 - 分布式协调与任务调度</a></p><hr><h3 id="监控与日志" tabindex="-1">监控与日志 <a class="header-anchor" href="#监控与日志" aria-label="Permalink to &quot;监控与日志&quot;">​</a></h3><p>高并发系统需要实时监控与日志分析。</p><ul><li><strong>Prometheus + Grafana</strong>（监控指标可视化）</li><li><strong>ELK Stack</strong>（Elasticsearch + Logstash + Kibana）</li><li><strong>SkyWalking / Zipkin / Jaeger</strong>（分布式链路追踪）</li></ul>',28)])])}const c=l(e,[["render",o]]);export{p as __pageData,c as default};
